rule: expr-activation
satisfies: APR-EXPR-019
representation: jsonc
expect: valid
evaluate: {"_today": "2026-09-01", "_now": "2026-09-01T12:00:00Z", "ctx": {"team": "records"}}
expects: {"responses": {"echo": "echo"}}
---
