  "aprVersion": "1.0-beta.6",
  "metadata": {
    "title": "T"
  },
  "sections": [
    {
      "id": "s",
      "title": "S",
      "prompts": [
        {
          "id": "_today",
          "label": "Today",
          "response": "stored"
        },
        {
          "id": "signed",
          "label": "Signed",
          "hints": {
            "exprValue": "_today"
          }
        }
      ]
    }
